import policy


def test_module_imports():
    assert hasattr(policy, "violations")


def test_valid_password_has_no_violations():
    assert policy.violations("Correct-Horse-42") == []


def test_short_password_breaks_length():
    assert "length" in policy.violations("Ab1")


def test_length_boundary_is_twelve():
    assert "length" not in policy.violations("Abcdefghij1k")
    assert "length" in policy.violations("Abcdefghij1")


def test_no_digit():
    assert policy.violations("Abcdefghijkl") == ["digit"]


def test_no_upper():
    assert policy.violations("abcdefghij1k") == ["upper"]


def test_no_lower():
    assert policy.violations("ABCDEFGHIJ1K") == ["lower"]


def test_whitespace_breaks_space():
    assert policy.violations("Abcdefghij 1k") == ["space"]
    assert policy.violations("Abcdefghij\t1k") == ["space"]


def test_banned_is_case_insensitive():
    assert policy.violations("Password12345", banned=["password12345"]) == ["banned"]


def test_banned_requires_exact_match():
    assert policy.violations("Correct-Horse-42", banned=["horse"]) == []


def test_all_violations_in_order():
    assert policy.violations("a b", banned=["a b"]) == [
        "length",
        "digit",
        "upper",
        "space",
        "banned",
    ]


def test_each_rule_reported_once():
    assert policy.violations("        ") == ["length", "digit", "upper", "lower", "space"]

